import fs from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { ANATOMY_DEFINITIONS } from "../packages/core/src/definitions.mjs"

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const check = process.argv.includes("--check")
const banner =
  "<!-- Generated by scripts/generate-definition-docs.mjs; edit the canonical source. -->\n\n"
const vocabulary =
  "# Built-in anatomy definitions\n\n" +
  "These Built-in definitions apply to residual div/span nodes after Predefined platform identities.\n" +
  "They produce Defined identities: choosing the right meaning remains an author decision.\n\n" +
  ANATOMY_DEFINITIONS.map(
    (entry) =>
      `## ${entry.canonicalName}\n\n${entry.description}\n\n` +
      `Examples: ${entry.examples.join("; ")}.\n\nExclusions: ${entry.excludes.join("; ")}.\n`,
  ).join("\n")
const outputs = new Map([
  ["docs/anatomy-definitions.md", banner + vocabulary],
  ["skills/nagi-css/references/anatomy-definitions.md", banner + vocabulary],
])
const github = "https://github.com/nagi-labs/nagi-css/blob/main/"
for (const [source, target] of [
  ["CONTRACT.md", "contract.md"],
  ["docs/definitions.md", "definitions.md"],
  ["docs/css-reference.md", "css-reference.md"],
]) {
  const input = await fs.readFile(path.join(root, source), "utf8")
  const converted = input.replace(/\]\(([^)]+)\)/gu, (match, href) => {
    if (/^(?:https?:|#)/u.test(href)) return match
    const resolved = path.posix.normalize(path.posix.join(path.posix.dirname(source), href))
    const [file, anchor] = resolved.split("#")
    const local = {
      "CONTRACT.md": "contract.md",
      "docs/definitions.md": "definitions.md",
      "docs/css-reference.md": "css-reference.md",
      "docs/anatomy-definitions.md": "anatomy-definitions.md",
      "skills/nagi-css/references/configuration.md": "configuration.md",
    }[file]
    return `](${local ? local + (anchor ? `#${anchor}` : "") : github + resolved})`
  })
  outputs.set(`skills/nagi-css/references/${target}`, banner + converted)
}
for (const [file, output] of outputs) {
  const destination = path.join(root, file)
  if (check) {
    if ((await fs.readFile(destination, "utf8").catch(() => "")) !== output)
      throw new Error(`Generated reference differs: ${file}; run vp run docs:generate`)
  } else await fs.writeFile(destination, output)
}
console.log(`${check ? "Verified" : "Generated"} ${outputs.size} definition and Skill references.`)
